def ways(n):
    '''爬到第 n 级楼梯的走法数：f(n) = f(n-1) + f(n-2)。'''
    if n <= 2:
        return n
    a, b = 1, 2
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b


