using int64 = long long;
// 相邻不能都偷，前 i 个的最大金额
int64 rob(const vector<int64> &a) {
    int64 prev = 0, cur = 0;
    for (int64 v : a) {
        int64 nxt = max(cur, prev + v);
        prev = cur;
        cur = nxt;
    }
    return cur;
}
