// 返回非空连续子数组的最大和
int64 max_subarray(const vector<int64> &a) {
    int64 cur = a[0], best = a[0];
    for (size_t i = 1; i < a.size(); ++i) {
        cur = max(a[i], cur + a[i]);
        best = max(best, cur);
    }
    return best;
}
